-- ES/DE/FR translations for the rest of France's deep-dive content:
-- page-level, stats, cards, steps, portal, penalty rows, lifecycle.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'CTC descentralizado (modelo Y)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Las listas de acreditación de PA, la postura de aplicación de sanciones y las especificaciones técnicas siguen evolucionando a medida que se acerca la puesta en marcha de septiembre de 2026 — confirme los requisitos actuales directamente con la DGFiP, la AIFE, o su Plateforme Agréée elegida antes de construir una integración.', 'La reforma francesa se desarrolla en dos vías paralelas — la facturación electrónica B2B estructurada y una obligación separada de "e-reporting" para todo lo que la facturación electrónica no cubre (B2C, transfronterizo). Ambas se implementan por fases según el tamaño de la empresa.', 'Francia es inusualmente flexible en cuanto a sintaxis — tres formatos distintos son legalmente aceptables, siempre que transporten los mismos datos subyacentes de EN 16931.', 'El "modelo Y" francés es deliberadamente descentralizado: a diferencia del sistema de compensación único del gobierno italiano, Francia autoriza a muchas plataformas privadas a realizar el intercambio real de facturas, con un único directorio público compartido que lo conecta todo.', 'No existe un único portal gubernamental de "regístrese aquí" para la propia facturación — el registro se realiza a través de la PA elegida, que después notifica al directorio nacional en su nombre.', 'La Ley de Finanzas para 2026 elevó considerablemente las multas legales — pero la DGFiP ha señalado públicamente un enfoque de aplicación temprana indulgente.' FROM countries WHERE name_en = 'France';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Dezentrales CTC (Y-Modell)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. PA-Akkreditierungslisten, die Durchsetzungshaltung bei Sanktionen und technische Spezifikationen entwickeln sich weiter, während sich der Start im September 2026 nähert — bestätigen Sie aktuelle Anforderungen direkt bei der DGFiP, der AIFE oder Ihrer gewählten Plateforme Agréée, bevor Sie eine Integration aufbauen.', 'Frankreichs Reform verläuft auf zwei parallelen Schienen — strukturierte B2B-E-Rechnungsstellung und eine separate "E-Reporting"-Pflicht für alles, was die E-Rechnungsstellung nicht abdeckt (B2C, grenzüberschreitend). Beide werden nach Unternehmensgröße gestaffelt eingeführt.', 'Frankreich ist bei der Syntax ungewöhnlich flexibel — drei verschiedene Formate sind alle rechtlich zulässig, solange sie dieselben zugrunde liegenden EN-16931-Daten tragen.', 'Frankreichs "Y-Modell" ist bewusst dezentralisiert: Anders als Italiens einzelnes staatliches Clearing-System lizenziert Frankreich viele private Plattformen für den eigentlichen Rechnungsaustausch, mit einem gemeinsamen öffentlichen Verzeichnis, das alles verbindet.', 'Es gibt kein einziges "Hier registrieren"-Regierungsportal für die Rechnungsstellung selbst — die Registrierung erfolgt über Ihre gewählte PA, die dann das nationale Verzeichnis in Ihrem Namen benachrichtigt.', 'Das Finanzgesetz 2026 hat die gesetzlichen Bußgelder erheblich angehoben — doch die DGFiP hat öffentlich einen nachsichtigen Ansatz bei der frühen Durchsetzung signalisiert.' FROM countries WHERE name_en = 'France';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'CTC décentralisé (modèle Y)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les listes d''accréditation des PA, la posture d''application des sanctions et les spécifications techniques continuent d''évoluer à l''approche du lancement de septembre 2026 — confirmez les exigences actuelles directement auprès de la DGFiP, de l''AIFE ou de votre Plateforme Agréée choisie avant de construire une intégration.', 'La réforme française se déroule selon deux voies parallèles — la facturation électronique B2B structurée et une obligation distincte d''« e-reporting » pour tout ce que la facturation électronique ne couvre pas (B2C, transfrontalier). Les deux sont déployées par phases selon la taille de l''entreprise.', 'La France est exceptionnellement flexible en matière de syntaxe — trois formats différents sont tous légalement acceptables, tant qu''ils véhiculent les mêmes données sous-jacentes conformes à l''EN 16931.', 'Le « modèle Y » français est délibérément décentralisé : contrairement au système de contrôle gouvernemental unique de l''Italie, la France autorise de nombreuses plateformes privées à effectuer l''échange effectif des factures, avec un annuaire public partagé unique reliant le tout.', 'Il n''existe pas de portail gouvernemental unique « inscrivez-vous ici » pour la facturation elle-même — l''inscription se fait via la PA choisie, qui notifie ensuite l''annuaire national en votre nom.', 'La loi de finances pour 2026 a considérablement relevé les amendes légales — mais la DGFiP a publiquement signalé une approche d''application clémente en phase initiale.' FROM countries WHERE name_en = 'France';

