INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formatos aceptados', '[["Híbrido", "Factur-X (PDF/A-3 + XML CII incrustado)"], ["XML estructurado (listo para Peppol)", "UBL 2.1"], ["XML estructurado (B2B complejo)", "UN/CEFACT CII"], ["PDF simple / adjunto de correo", "Ya no válido desde la Ola 1"]]', 'Factur-X es la elección más distintivamente "francesa" — el PDF incrustado conserva una copia legible por humanos para el personal que aún abre facturas a simple vista, mientras que la capa XML realiza el procesamiento automático.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'file_format' AND dct.title = 'Accepted formats';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Akzeptierte Formate', '[["Hybrid", "Factur-X (PDF/A-3 + eingebettetes CII-XML)"], ["Strukturiertes XML (Peppol-bereit)", "UBL 2.1"], ["Strukturiertes XML (komplexes B2B)", "UN/CEFACT CII"], ["Einfaches PDF / E-Mail-Anhang", "Ab Welle 1 nicht mehr gültig"]]', 'Factur-X ist die charakteristischste "französische" Wahl — das eingebettete PDF bewahrt eine für Menschen lesbare Kopie für Mitarbeiter, die Rechnungen noch mit bloßem Auge öffnen, während die XML-Schicht die maschinelle Verarbeitung übernimmt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'file_format' AND dct.title = 'Accepted formats';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Formats acceptés', '[["Hybride", "Factur-X (PDF/A-3 + XML CII intégré)"], ["XML structuré (prêt pour Peppol)", "UBL 2.1"], ["XML structuré (B2B complexe)", "UN/CEFACT CII"], ["PDF simple / pièce jointe e-mail", "Plus valable depuis la Vague 1"]]', 'Factur-X est le choix le plus typiquement « français » — le PDF intégré conserve une copie lisible par l''humain pour le personnel qui ouvre encore les factures à l''œil, tandis que la couche XML assure le traitement automatisé.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'file_format' AND dct.title = 'Accepted formats';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Norma que rige', '[["Modelo semántico europeo", "EN 16931"], ["Especificación técnica nacional", "AFNOR XP Z12-012"], ["Cubre", "Formatos, listas de códigos, reglas de negocio, estados del ciclo de vida (XP Z12-013)"], ["Tamaño del conjunto de reglas", "~112 reglas de Factur-X 1.0.06"]]', 'AFNOR XP Z12-012 es la referencia maestra — define el modelo semántico y la sintaxis para cada formato aceptado, además del XML de e-reporting y los mensajes de estado del ciclo de vida, por lo que cualquier PA o desarrollo propio debería validarse directamente contra ella.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'file_format' AND dct.title = 'Governing standard';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Maßgeblicher Standard', '[["Europäisches semantisches Modell", "EN 16931"], ["Nationale technische Spezifikation", "AFNOR XP Z12-012"], ["Umfasst", "Formate, Codelisten, Geschäftsregeln, Lebenszyklusstatus (XP Z12-013)"], ["Regelwerksgröße", "~112 Factur-X-1.0.06-Regeln"]]', 'AFNOR XP Z12-012 ist die Hauptreferenz — sie definiert das semantische Modell und die Syntax für jedes akzeptierte Format sowie das E-Reporting-XML und die Lebenszyklus-Statusmeldungen, sodass jede PA oder Eigenentwicklung direkt dagegen validiert werden sollte.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'file_format' AND dct.title = 'Governing standard';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Norme de référence', '[["Modèle sémantique européen", "EN 16931"], ["Spécification technique nationale", "AFNOR XP Z12-012"], ["Couvre", "Formats, listes de codes, règles métier, statuts de cycle de vie (XP Z12-013)"], ["Taille du jeu de règles", "~112 règles Factur-X 1.0.06"]]', 'AFNOR XP Z12-012 est la référence maîtresse — elle définit le modèle sémantique et la syntaxe de chaque format accepté ainsi que le XML d''e-reporting et les messages de statut de cycle de vie, donc toute PA ou développement interne devrait être validé directement par rapport à elle.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'file_format' AND dct.title = 'Governing standard';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores obligatorios', '[["SIREN", "Identificador de entidad legal de 9 dígitos"], ["SIRET", "Identificador de establecimiento de 14 dígitos (SIREN + 5)"], ["Canal de recepción", "PA elegida por el destinatario, según su entrada en el directorio"]]', 'Toda factura debe resolverse en una dirección de enrutamiento correcta a nivel SIRET en el directorio nacional — si esto es incorrecto, la PA no podrá entregar la factura, independientemente de si el XML en sí es válido.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'file_format' AND dct.title = 'Mandatory identifiers';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtkennungen', '[["SIREN", "9-stellige Kennung der juristischen Person"], ["SIRET", "14-stellige Betriebsstättenkennung (SIREN + 5)"], ["Empfangskanal", "Vom Empfänger gewählte PA, gemäß Verzeichniseintrag"]]', 'Jede Rechnung muss sich im nationalen Verzeichnis zu einer korrekten SIRET-Ebenen-Routing-Adresse auflösen — ist dies falsch, kann die PA die Rechnung nicht zustellen, unabhängig davon, ob das XML selbst gültig ist.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'file_format' AND dct.title = 'Mandatory identifiers';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants obligatoires', '[["SIREN", "Identifiant d''entité légale à 9 chiffres"], ["SIRET", "Identifiant d''établissement à 14 chiffres (SIREN + 5)"], ["Canal de réception", "PA choisie par le destinataire, selon son entrée dans l''annuaire"]]', 'Chaque facture doit se résoudre vers une adresse de routage correcte au niveau SIRET dans l''annuaire national — une erreur ici empêche la PA de livrer la facture, indépendamment de la validité du XML lui-même.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'file_format' AND dct.title = 'Mandatory identifiers';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Archivo', '[["Periodo de conservación", "10 años"], ["Formato a conservar", "Formato electrónico original, con integridad garantizada"]]', 'Archivar la representación en PDF de una factura Factur-X no es suficiente por sí solo — el archivo estructurado original (con el XML incrustado) es lo que debe conservarse durante los 10 años completos.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'file_format' AND dct.title = 'Archiving';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Archivierung', '[["Aufbewahrungsfrist", "10 Jahre"], ["Zu archivierendes Format", "Ursprüngliches elektronisches Format, mit garantierter Integrität"]]', 'Die Archivierung der PDF-Darstellung einer Factur-X-Rechnung allein reicht nicht aus — die ursprüngliche strukturierte Datei (mit eingebettetem XML) muss die vollen 10 Jahre aufbewahrt werden.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'file_format' AND dct.title = 'Archiving';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Archivage', '[["Durée de conservation", "10 ans"], ["Format à conserver", "Format électronique d''origine, intégrité garantie"]]', 'Archiver le rendu PDF d''une facture Factur-X ne suffit pas en soi — c''est le fichier structuré d''origine (avec le XML intégré) qui doit être conservé pendant les 10 années complètes.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'file_format' AND dct.title = 'Archiving';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Arquitectura de red', '[["Modelo", "CTC descentralizado (\"modelo Y\")"], ["Intercambio de facturas", "A través de una Plateforme Agréée (PA) certificada"], ["Directorio central", "PPF (Portail Public de Facturation) — annuaire"], ["Opción solo software", "Solution Compatible (SC) — debe seguir enrutando a través de una PA"]]', 'La PPF en sí ya no intercambia facturas — es el directorio nacional y el concentrador de enrutamiento/reporte. Todo el envío y recepción real de facturas estructuradas ocurre a través de su PA elegida (o una SC superpuesta a una).', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'scope_transmission' AND dct.title = 'Network architecture';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Netzwerkarchitektur', '[["Modell", "Dezentralisiertes CTC (\"Y-Modell\")"], ["Rechnungsaustausch", "Über eine zertifizierte Plateforme Agréée (PA)"], ["Zentrales Verzeichnis", "PPF (Portail Public de Facturation) — annuaire"], ["Reine Software-Option", "Solution Compatible (SC) — muss weiterhin über eine PA leiten"]]', 'Die PPF selbst tauscht keine Rechnungen mehr aus — sie ist das nationale Verzeichnis und der Routing-/Meldungs-Konzentrator. Der eigentliche Versand und Empfang strukturierter Rechnungen erfolgt über Ihre gewählte PA (oder eine SC darauf aufgesetzt).', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'scope_transmission' AND dct.title = 'Network architecture';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Architecture réseau', '[["Modèle", "CTC décentralisé (« modèle Y »)"], ["Échange de factures", "Via une Plateforme Agréée (PA) certifiée"], ["Annuaire central", "PPF (Portail Public de Facturation)"], ["Option logicielle seule", "Solution Compatible (SC) — doit tout de même transiter par une PA"]]', 'Le PPF lui-même n''échange plus de factures — il s''agit de l''annuaire national et du concentrateur de routage/déclaration. L''envoi et la réception effectifs des factures structurées se font via votre PA choisie (ou une SC superposée à celle-ci).', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'scope_transmission' AND dct.title = 'Network architecture';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Cadencia del e-reporting', '[["Alcance", "Ventas B2C y transacciones transfronterizas"], ["Base legal", "Artículo 290 del CGI"], ["Cadencia del régimen de IVA estándar", "Dentro de 7 días, por periodo de 10 días"]]', 'El e-reporting no es en tiempo real — no lo sobrediseñe para una transmisión instantánea. Funciona con un ciclo de periodo de 10 días y una ventana de envío de 7 días, distinto de los estados del ciclo de vida a nivel de factura descritos arriba.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'scope_transmission' AND dct.title = 'E-reporting cadence';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'E-Reporting-Rhythmus', '[["Umfang", "B2C-Verkäufe & grenzüberschreitende Transaktionen"], ["Rechtsgrundlage", "CGI Artikel 290"], ["Rhythmus im Standard-Umsatzsteuerregime", "Innerhalb von 7 Tagen, je 10-Tages-Zeitraum"]]', 'E-Reporting erfolgt nicht in Echtzeit — überkonstruieren Sie nicht für eine sofortige Übermittlung. Es läuft in einem 10-Tages-Zyklus mit einem 7-Tage-Übermittlungsfenster, getrennt von den oben beschriebenen Rechnungsebene-Lebenszyklusstatus.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'scope_transmission' AND dct.title = 'E-reporting cadence';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Cadence de l''e-reporting', '[["Champ d''application", "Ventes B2C et transactions transfrontalières"], ["Base légale", "Article 290 du CGI"], ["Cadence du régime de TVA standard", "Sous 7 jours, par période de 10 jours"]]', 'L''e-reporting n''est pas en temps réel — ne le surdimensionnez pas pour une transmission instantanée. Il fonctionne selon un cycle de période de 10 jours avec une fenêtre de soumission de 7 jours, distinct des statuts de cycle de vie au niveau de la facture décrits ci-dessus.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'scope_transmission' AND dct.title = 'E-reporting cadence';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Protecciones de continuidad de la plataforma', '[["Continuidad mínima del servicio", "1 año tras cambiar de PA"], ["Requisito de conectividad de la PA", "Debe soportar Factur-X, UBL y CII"]]', 'Si cambia de proveedor, su antigua PA está legalmente obligada a seguir prestándole servicio durante al menos un año — una salvaguarda frente a quedar atrapado en una plataforma que deja de ajustarse a sus necesidades.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'scope_transmission' AND dct.title = 'Platform continuity protections';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Schutz der Plattformkontinuität', '[["Mindestdienstkontinuität", "1 Jahr nach PA-Wechsel"], ["PA-Konnektivitätsanforderung", "Muss Factur-X, UBL und CII unterstützen"]]', 'Wenn Sie den Anbieter wechseln, ist Ihre bisherige PA gesetzlich verpflichtet, Sie mindestens ein weiteres Jahr zu bedienen — eine Schutzmaßnahme dagegen, an eine Plattform gebunden zu bleiben, die nicht mehr zu Ihren Bedürfnissen passt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'scope_transmission' AND dct.title = 'Platform continuity protections';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Protections de continuité de plateforme', '[["Continuité de service minimale", "1 an après changement de PA"], ["Exigence de connectivité PA", "Doit prendre en charge Factur-X, UBL et CII"]]', 'Si vous changez de prestataire, votre ancienne PA est légalement tenue de continuer à vous servir pendant au moins un an — une protection contre le fait d''être bloqué sur une plateforme qui ne convient plus.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'scope_transmission' AND dct.title = 'Platform continuity protections';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🕊️ Indulgencia en la aplicación temprana', NULL, NULL, 'La Directora General de la DGFiP, Amélie Verdier, confirmó en el E-Invoicing Day de mayo de 2026 que las sanciones no se aplicarán automáticamente desde el primer día — las empresas que demuestren un esfuerzo genuino de implementación obtienen un "derecho a equivocarse" durante la implementación inicial, con una aplicación suavizada que se espera continúe al menos hasta enero de 2027.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'penalties_related' AND dct.title = '🕊️ Early enforcement leniency';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🕊️ Nachsicht bei früher Durchsetzung', NULL, NULL, 'DGFiP-Generaldirektorin Amélie Verdier bestätigte beim E-Invoicing Day im Mai 2026, dass Sanktionen nicht automatisch vom ersten Tag an verhängt werden — Unternehmen, die echte Umsetzungsbemühungen zeigen, erhalten während der anfänglichen Einführung ein "Recht auf Fehler", wobei die abgeschwächte Durchsetzung voraussichtlich mindestens bis Januar 2027 andauert.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'penalties_related' AND dct.title = '🕊️ Early enforcement leniency';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🕊️ Clémence dans l''application précoce', NULL, NULL, 'La directrice générale de la DGFiP, Amélie Verdier, a confirmé lors de l''E-Invoicing Day de mai 2026 que les sanctions ne seront pas appliquées automatiquement dès le premier jour — les entreprises démontrant un véritable effort de mise en œuvre bénéficient d''un « droit à l''erreur » pendant le déploiement initial, avec un assouplissement de l''application attendu au moins jusqu''en janvier 2027.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'penalties_related' AND dct.title = '🕊️ Early enforcement leniency';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⏳ Periodo de gracia para la conexión a la plataforma', NULL, NULL, 'Si la DGFiP determina que no está conectado a una plataforma acreditada para recibir facturas electrónicas, recibirá un aviso formal y tres meses para registrarse con una PA antes de que se aplique el régimen de multas de 50 €/factura.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'penalties_related' AND dct.title = '⏳ Platform-connection grace period';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⏳ Übergangsfrist für die Plattformanbindung', NULL, NULL, 'Stellt die DGFiP fest, dass Sie nicht an eine akkreditierte Plattform zum Empfang von E-Rechnungen angebunden sind, erhalten Sie eine förmliche Mitteilung und drei Monate Zeit, sich bei einer PA zu registrieren, bevor die Bußgeldregelung von 50 €/Rechnung greift.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'penalties_related' AND dct.title = '⏳ Platform-connection grace period';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⏳ Période de grâce pour la connexion à une plateforme', NULL, NULL, 'Si la DGFiP constate que vous n''êtes pas connecté à une plateforme accréditée pour recevoir des factures électroniques, vous recevez une mise en demeure et trois mois pour vous inscrire auprès d''une PA avant que le régime d''amende de 50 €/facture ne s''applique.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'penalties_related' AND dct.title = '⏳ Platform-connection grace period';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📎 Base legal', NULL, NULL, 'El artículo 123 de la Ley n.º 2026-103 (19 de febrero de 2026) modifica los artículos 289 bis, 289 E, 290, 1737 y 1788 D del CGI — esta es la referencia a consultar si necesita la fuente primaria en lugar de un resumen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'penalties_related' AND dct.title = '📎 Legal basis';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📎 Rechtsgrundlage', NULL, NULL, 'Artikel 123 des Gesetzes Nr. 2026-103 (19. Februar 2026) ändert die CGI-Artikel 289 bis, 289 E, 290, 1737 und 1788 D — dies ist die Fundstelle, die Sie prüfen sollten, wenn Sie die Primärquelle statt einer Zusammenfassung benötigen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'penalties_related' AND dct.title = '📎 Legal basis';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📎 Base légale', NULL, NULL, 'L''article 123 de la loi n° 2026-103 (19 février 2026) modifie les articles 289 bis, 289 E, 290, 1737 et 1788 D du CGI — c''est la référence à consulter si vous avez besoin de la source primaire plutôt que d''un résumé.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'France' AND dc.section = 'penalties_related' AND dct.title = '📎 Legal basis';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija una Plateforme Agréée (PA)', 'Seleccione de la lista publicada por la DGFiP de plataformas acreditadas (más de 100 a enero de 2026), según el soporte de formatos, la integración con su software contable y si también gestiona el e-reporting. Una "Solution Compatible" (SC) puede situarse sobre una PA si prefiere su software actual, pero no puede conectarse directamente al directorio.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Choose a Plateforme Agréée (PA)';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie eine Plateforme Agréée (PA)', 'Wählen Sie aus der von der DGFiP veröffentlichten Liste akkreditierter Plattformen (über 100 Stand Januar 2026), basierend auf Formatunterstützung, Integration mit Ihrer Buchhaltungssoftware und ob auch E-Reporting abgedeckt wird. Eine "Solution Compatible" (SC) kann auf einer PA aufsetzen, wenn Sie Ihre bestehende Software bevorzugen, kann sich aber nicht direkt mit dem Verzeichnis verbinden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Choose a Plateforme Agréée (PA)';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez une Plateforme Agréée (PA)', 'Sélectionnez parmi la liste publiée par la DGFiP des plateformes accréditées (plus de 100 en janvier 2026), selon la prise en charge des formats, l''intégration avec votre logiciel comptable et si elle gère aussi l''e-reporting. Une « Solution Compatible » (SC) peut s''appuyer sur une PA si vous préférez votre logiciel existant, mais elle ne peut pas se connecter directement à l''annuaire.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Choose a Plateforme Agréée (PA)';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Proporcione los datos SIREN/SIRET de su empresa', 'Su PA recopila sus identificadores de entidad legal, su preferencia de canal de recepción y la fecha prevista de puesta en marcha de la facturación electrónica como parte de la incorporación.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Provide your company''s SIREN/SIRET details';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Geben Sie die SIREN-/SIRET-Daten Ihres Unternehmens an', 'Ihre PA erfasst im Rahmen des Onboardings Ihre Kennungen der juristischen Person, Ihre Präferenz für den Empfangskanal und das geplante Startdatum der E-Rechnungsstellung.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Provide your company''s SIREN/SIRET details';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Fournissez les informations SIREN/SIRET de votre entreprise', 'Votre PA recueille vos identifiants d''entité légale, votre préférence de canal de réception et votre date de mise en route prévue pour la facturation électronique dans le cadre de l''intégration.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Provide your company''s SIREN/SIRET details';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme su entrada en el directorio (annuaire)', 'Revise y confirme la información de su empresa, el canal de recepción elegido (su PA), la dirección de facturación electrónica y la fecha de inicio del servicio. Su PA transmite esto a la AIFE (Agence pour l''Informatique Financière de l''État) y a la DGFiP, quienes completan el directorio nacional utilizado para enrutarle las facturas.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Confirm your directory (annuaire) entry';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie Ihren Verzeichnis- (annuaire-)Eintrag', 'Überprüfen und bestätigen Sie Ihre Unternehmensangaben, den gewählten Empfangskanal (Ihre PA), die E-Rechnungsadresse und das Startdatum des Dienstes. Ihre PA übermittelt dies an die AIFE (Agence pour l''Informatique Financière de l''État) und die DGFiP, die das nationale Verzeichnis pflegen, über das Rechnungen an Sie weitergeleitet werden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Confirm your directory (annuaire) entry';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez votre entrée dans l''annuaire', 'Vérifiez et confirmez les informations de votre entreprise, le canal de réception choisi (votre PA), l''adresse de facturation électronique et la date de début de service. Votre PA transmet ces informations à l''AIFE (Agence pour l''Informatique Financière de l''État) et à la DGFiP, qui alimentent l''annuaire national utilisé pour vous router les factures.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Confirm your directory (annuaire) entry';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Pruebe la generación de formatos y la gestión de estados del ciclo de vida', 'Valide que su ERP o las herramientas de la PA pueden generar salidas conformes en Factur-X, UBL o CII, y que sus sistemas consumen y emiten correctamente los estados del ciclo de vida (Depositada, Enviada, Recibida, Aprobada/Rechazada, Pago Pendiente/Realizado).' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Test format generation and lifecycle status handling';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Testen Sie die Formaterzeugung und die Handhabung des Lebenszyklusstatus', 'Prüfen Sie, dass Ihr ERP oder die Tools der PA konforme Factur-X-, UBL- oder CII-Ausgaben erzeugen können und dass Ihre Systeme die Lebenszyklusstatus (Hinterlegt, Gesendet, Empfangen, Genehmigt/Abgelehnt, Zahlung fällig/erfolgt) korrekt verarbeiten und ausgeben.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Test format generation and lifecycle status handling';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Testez la génération de format et la gestion des statuts de cycle de vie', 'Vérifiez que votre ERP ou les outils de la PA peuvent générer une sortie conforme Factur-X, UBL ou CII, et que vos systèmes consomment et émettent correctement les statuts de cycle de vie (Déposée, Envoyée, Reçue, Approuvée/Rejetée, Paiement Dû/Effectué).' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Test format generation and lifecycle status handling';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure el e-reporting para ventas B2C y transfronterizas', 'Configure una transmisión separada para las transacciones fuera del alcance B2B nacional — estas siguen la cadencia de e-reporting de periodo de 10 días/ventana de 7 días en lugar del seguimiento del ciclo de vida factura por factura.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Set up e-reporting for B2C and cross-border sales';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie E-Reporting für B2C- und grenzüberschreitende Verkäufe ein', 'Konfigurieren Sie eine separate Übermittlung für Transaktionen außerhalb des inländischen B2B-Anwendungsbereichs — diese folgen dem 10-Tages-Zeitraum-/7-Tage-Fenster-E-Reporting-Rhythmus statt der rechnungsweisen Lebenszyklusverfolgung.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Set up e-reporting for B2C and cross-border sales';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place l''e-reporting pour les ventes B2C et transfrontalières', 'Configurez une transmission distincte pour les transactions hors du champ B2B domestique — celles-ci suivent la cadence d''e-reporting en période de 10 jours/fenêtre de 7 jours plutôt que le suivi de cycle de vie facture par facture.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Set up e-reporting for B2C and cross-border sales';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Mantenga actualizada su entrada en el directorio', 'Si cambia de PA o de canal de recepción, actualice el directorio con prontitud — su antigua PA debe mantener un mínimo de un año de continuidad, pero el propio directorio debe reflejar el cambio para que las facturas se enruten correctamente.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Keep your directory entry current';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Halten Sie Ihren Verzeichniseintrag aktuell', 'Wenn Sie die PA wechseln oder Ihren Empfangskanal ändern, aktualisieren Sie das Verzeichnis umgehend — Ihre bisherige PA muss mindestens ein Jahr Kontinuität gewährleisten, doch das Verzeichnis selbst muss die Änderung widerspiegeln, damit Rechnungen korrekt weitergeleitet werden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Keep your directory entry current';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Maintenez votre entrée d''annuaire à jour', 'Si vous changez de PA ou de canal de réception, mettez à jour l''annuaire rapidement — votre ancienne PA doit maintenir une continuité minimale d''un an, mais l''annuaire lui-même doit refléter le changement pour que les factures soient correctement routées.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'France' AND dst.title = 'Keep your directory entry current';

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Chorus Pro / PPF' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'France';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Chorus Pro / PPF' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'France';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Chorus Pro / PPF' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'France';

